type ParentGoldenDelivery = (
    xai_grok_tools::implementations::grok_build::task::types::ActiveAgentMessageDelivery,
    tokio::sync::oneshot::Sender<
        xai_grok_tools::implementations::grok_build::task::coordinator::ActiveMessageAdmission,
    >,
);

struct ParentGoldenControl(tokio::sync::mpsc::UnboundedSender<ParentGoldenDelivery>);

impl xai_grok_tools::implementations::grok_build::task::coordinator::ChildControl
    for ParentGoldenControl
{
    type ProgressFuture = std::future::Ready<
        xai_grok_tools::implementations::grok_build::task::coordinator::SubagentProgress,
    >;
    fn progress(&self) -> Self::ProgressFuture {
        std::future::ready(Default::default())
    }
    fn send_active_message(
        &self,
        delivery: xai_grok_tools::implementations::grok_build::task::types::ActiveAgentMessageDelivery,
    ) -> xai_grok_tools::implementations::grok_build::task::coordinator::SendBoxFuture<
        xai_grok_tools::implementations::grok_build::task::coordinator::ActiveMessageAdmission,
    > {
        let (tx, rx) = tokio::sync::oneshot::channel();
        self.0.send((delivery, tx)).unwrap();
        Box::pin(async { rx.await.unwrap() })
    }
    fn cancel(&self) {}
}

struct ParentGoldenRunner {
    deliveries: tokio::sync::mpsc::UnboundedSender<ParentGoldenDelivery>,
    started: tokio::sync::mpsc::UnboundedSender<()>,
}

impl xai_grok_tools::implementations::grok_build::task::coordinator::ChildRunner
    for ParentGoldenRunner
{
    type Control = ParentGoldenControl;
    type CompletionData = ();
    type RunFuture = xai_grok_tools::implementations::grok_build::task::coordinator::LocalBoxFuture<
        xai_grok_tools::implementations::grok_build::task::coordinator::ChildRunOutput<()>,
    >;
    type ValidateFuture = std::future::Pending<
        xai_grok_tools::implementations::grok_build::task::types::SubagentValidateTypeOutcome,
    >;
    type DescribeFuture = std::future::Pending<
        xai_grok_tools::implementations::grok_build::task::types::SubagentDescribeOutcome,
    >;
    fn run(
        &self,
        run: xai_grok_tools::implementations::grok_build::task::coordinator::ChildRunRequest<
            Self::Control,
        >,
    ) -> Self::RunFuture {
        let deliveries = self.deliveries.clone();
        let started = self.started.clone();
        Box::pin(async move {
            assert!(run.reporter.started(xai_grok_tools::implementations::grok_build::task::coordinator::StartedChild {
                child_session_id: run.request.id.clone(), persona: None, resumed_from: None,
                child_cwd: String::new(), worktree_path: None, effective_model_id: "parent-fixture".into(),
                definition_background: true, control: ParentGoldenControl(deliveries),
            }).await);
            started.send(()).unwrap();
            run.cancellation.cancelled().await;
            xai_grok_tools::implementations::grok_build::task::coordinator::ChildRunOutput {
                result: xai_grok_tools::implementations::grok_build::task::types::SubagentResult {
                    subagent_id: run.request.id.clone(),
                    child_session_id: run.request.id,
                    cancelled: true,
                    ..Default::default()
                },
                completion_data: (),
                snapshot_ref: None,
            }
        })
    }
    fn validate_type(&self, _: String, _: String) -> Self::ValidateFuture {
        std::future::pending()
    }
    fn describe_type(&self, _: String, _: Option<String>, _: String) -> Self::DescribeFuture {
        std::future::pending()
    }
    fn supports_wake(&self) -> bool {
        false
    }
    fn on_completed(
        &self,
        _: xai_grok_tools::implementations::grok_build::task::coordinator::ChildCompletion<()>,
        published: Box<dyn FnOnce() + Send>,
    ) {
        published();
    }
}

async fn parent_golden_delivery_fixture() -> (
    xai_grok_tools::implementations::grok_build::task::backend::ChannelBackend,
    tokio::sync::mpsc::UnboundedReceiver<ParentGoldenDelivery>,
    tokio::task::JoinHandle<()>,
) {
    use xai_grok_tools::implementations::grok_build::task::{
        backend::SubagentBackend, coordinator::SubagentCoordinator,
    };
    let (tx, rx) = SubagentCoordinator::<ParentGoldenRunner>::channel();
    let (deliveries, delivery_rx) = tokio::sync::mpsc::unbounded_channel();
    let (started, mut started_rx) = tokio::sync::mpsc::unbounded_channel();
    let coordinator = SubagentCoordinator::from_channel(
        rx,
        ParentGoldenRunner {
            deliveries,
            started,
        },
        Default::default(),
    );
    let task = tokio::task::spawn_local(coordinator.run());
    let backend = xai_grok_tools::implementations::grok_build::task::backend::ChannelBackend::for_coordinator_session(tx, "parent-lifecycle");
    let request = xai_grok_tools::implementations::grok_build::task::types::SubagentRequest {
        id: "lifecycle-child".into(),
        prompt: "fixture".into(),
        description: "local lifecycle only".into(),
        subagent_type: "explore".into(),
        parent_session_id: "parent-lifecycle".into(),
        parent_prompt_id: Some("parent-prompt".into()),
        resume_from: None,
        cwd: None,
        runtime_overrides: Default::default(),
        run_in_background: true,
        surface_completion: false,
        await_to_completion: false,
        fork_context: false,
        context: Default::default(),
        owner: Default::default(),
        cancel_token: tokio_util::sync::CancellationToken::new(),
        spawn_root: Default::default(),
    };
    {
        let spawned = backend.spawn(request, None);
        tokio::pin!(spawned);
        tokio::select! {
            _ = started_rx.recv() => {},
            result = &mut spawned => { result.unwrap(); started_rx.recv().await.unwrap(); },
        }
    }
    (backend, delivery_rx, task)
}

async fn parent_golden_fork_snapshot(fixture: &mut ParentGoldenFixture) -> Vec<ToolSpec> {
    let (event_tx, event_rx) = tokio::sync::mpsc::unbounded_channel();
    std::sync::Arc::get_mut(&mut fixture.actor)
        .unwrap()
        .event_tx = event_tx;
    let (commands, command_rx) = tokio::sync::mpsc::unbounded_channel();
    let (_chat_tx, chat_rx) = tokio::sync::mpsc::unbounded_channel();
    let task = tokio_util::task::AbortOnDropHandle::new(tokio::task::spawn_local(
        super::super::run_session(
            fixture.actor.clone(),
            command_rx,
            chat_rx,
            event_rx,
            None,
            std::sync::Arc::new(parking_lot::Mutex::new(
                xai_grok_workspace::file_system::CodebaseIndexManager::new(),
            )),
            fixture.actor.tool_context.cwd.as_path().to_path_buf(),
            crate::session::fs_watch::FsWatchCapabilities::none(),
        ),
    ));
    let (respond_to, reply) = tokio::sync::oneshot::channel();
    commands
        .send(crate::session::commands::SessionCommand::SnapshotToolDefinitions { respond_to })
        .unwrap();
    let snapshot = tokio::time::timeout(std::time::Duration::from_secs(30), reply)
        .await
        .expect("actual parent snapshot reply")
        .unwrap();
    task.abort();
    let _ = task.await;
    assert!(
        fixture.wire.exchanges.borrow().is_empty(),
        "snapshot does not submit inference"
    );
    assert!(snapshot.iter().any(|tool| tool.name == "search_tool"));
    assert!(snapshot.iter().any(|tool| tool.name == "use_tool"));
    assert!(!snapshot.iter().any(|tool| {
        ["policy__root_message", "alpha__lookup", "zeta__fetch"].contains(&tool.name.as_str())
    }));
    snapshot
}

#[tokio::test(flavor = "current_thread")]
async fn interim_messages_discovery_holds_cleanup_and_refusals() {
    const NAME: &str = "session::acp_session::sampler_turn::tests::interim_messages_discovery_holds_cleanup_and_refusals";
    if parent_golden_isolated(NAME) {
        return;
    }
    tokio::task::LocalSet::new().run_until(async {
        use xai_grok_tools::implementations::grok_build::task::backend::SubagentBackend;
        use xai_grok_tools::implementations::grok_build::task::coordinator::ActiveMessageAdmission;
        use xai_grok_tools::implementations::grok_build::task::types::{ActiveAgentMessageRequest, ActiveAgentMessageOperation};
        let history = parent_golden_history();
        let discovery: Vec<_> = history.iter().filter(|item| item.discovery().is_some()).cloned().collect();
        let cases = vec![
            ("all-complete", discovery.clone()),
            ("call-only", vec![discovery[0].clone()]),
            ("output-only", vec![discovery[1].clone()]),
            ("server-use-only", vec![discovery[2].clone()]),
            ("server-result-only", vec![discovery[3].clone()]),
            ("out-of-order", vec![discovery[1].clone(), discovery[0].clone(), discovery[3].clone(), discovery[2].clone()]),
            ("no-discovery", Vec::new()),
        ];
        for (label, members) in cases {
            let fixture = parent_golden_fixture(ApiBackend::Messages).await;
            let mut input = vec![ConversationItem::system("Lifecycle parent"), ConversationItem::user("Lifecycle request")];
            input.extend(members);
            fixture.actor.chat_state_handle.replace_conversation(input.clone());
            let before = fixture.actor.chat_state_handle.get_conversation().await;
            for text in ["human-first", "human-second"] {
                fixture.actor.pending_interjections.push(crate::session::acp_session::PendingInterjection { text: text.into(), attachments: Vec::new() });
            }
            let human_delivery = fixture.actor.drain_admitted_messages_at_safe_point().await;
            let after_human = fixture.actor.chat_state_handle.get_conversation().await;
            let empty_human = fixture.actor.drain_admitted_messages_at_safe_point().await;
            {
                let mut state = fixture.actor.state.lock().await;
                state.pending_inputs.push_back(support::user_item("lifecycle-running", "owner"));
                state.running_task = Some(support::running_task_stub("lifecycle-running"));
            }
            let (backend, mut deliveries, coordinator_task) = parent_golden_delivery_fixture().await;
            let mut admissions = Vec::new();
            let mut receipts = Vec::new();
            for text in ["parent-first", "parent-second"] {
                let (sink, mut receipt_rx) = tokio::sync::mpsc::channel(1);
                let (respond_to, response) = tokio::sync::oneshot::channel();
                let (completion, _) = tokio::sync::mpsc::unbounded_channel();
                let ingress = backend.send_active_message(ActiveAgentMessageRequest::try_new_with_operation(
                    "lifecycle-child", text, ActiveAgentMessageOperation::Steer,
                ).unwrap());
                tokio::pin!(ingress);
                let (delivery, admitted_tx) = tokio::select! {
                    delivery = deliveries.recv() => delivery.unwrap(),
                    outcome = &mut ingress => panic!("coordinator must hand off a real delivery: {outcome:?}"),
                };
                fixture.actor.admit_parent_agent_message(
                    delivery, sink,
                    xai_grok_telemetry::TelemetryCtx::new("parent-lifecycle".into(), std::sync::Arc::new(tokio::sync::Mutex::new(0))),
                    respond_to, completion,
                ).await;
                let admission = response.await.unwrap();
                assert_eq!(admission, ActiveMessageAdmission::Admitted);
                admissions.push(format!("{admission:?}"));
                admitted_tx.send(admission).unwrap();
                assert!(matches!(ingress.await, xai_grok_tools::implementations::grok_build::task::types::ActiveAgentMessageOutcome::Accepted { .. }));
                receipts.push(receipt_rx.recv().await.unwrap());
            }
            let before_release = fixture.actor.chat_state_handle.get_conversation().await;
            let parent_delivery = fixture.actor.drain_parent_messages_at_safe_point().await;
            let after_parent = fixture.actor.chat_state_handle.get_conversation().await;
            let empty_parent = fixture.actor.drain_parent_messages_at_safe_point().await;
            let mut cleaned = input.clone();
            crate::session::helpers::session_recap::pop_trailing_tool_run(&mut cleaned);
            let removed: Vec<_> = input.iter().filter(|original| !cleaned.iter().any(|retained| serde_json::to_value(original).unwrap() == serde_json::to_value(retained).unwrap())).cloned().collect();
            let frozen = serde_json::json!({
                "input":before, "human_delivery":human_delivery,
                "human_pending_after":usize::from(!fixture.actor.pending_interjections.is_empty()),
                "after_human":after_human, "no_human_work":empty_human,
                "parent_admissions":admissions, "before_parent_release":before_release,
                "parent_delivery":parent_delivery, "after_parent":after_parent,
                "no_parent_work":empty_parent, "cleanup_retained":cleaned, "cleanup_removed":removed,
            });
            parent_golden_record(&format!("lifecycle-holds/{label}"), serde_json::json!({"frozen":frozen}));
            drop(receipts);
            coordinator_task.abort();
            let _ = coordinator_task.await;
        }
        for registration in ["matching", "missing", "unrelated"] {
            let mut parent = parent_golden_fixture(ApiBackend::Messages).await;
            let parent_registry = parent_golden_registry(&parent.actor);
            let snapshot = parent_golden_fork_snapshot(&mut parent).await;
            assert_eq!(serde_json::to_value(parent.actor.chat_state_handle.get_conversation().await).unwrap(), serde_json::to_value(&parent.history).unwrap());
            let mut fixture = parent_golden_fixture(ApiBackend::Messages).await;
            if registration != "matching" {
                fixture.actor.agent.replace(support::test_agent_with_tools(Vec::new()).await);
                if registration == "unrelated" {
                    for name in ["search_tool", "use_tool"] {
                        parent_golden_register(&fixture.actor, name, xai_grok_tools::types::tool::ToolNamespace::GrokBuild, xai_grok_tools::types::tool::ToolKind::Other);
                    }
                }
            }
            let actor = std::sync::Arc::get_mut(&mut fixture.actor).unwrap();
            actor.startup_hints.is_subagent = true;
            actor.startup_hints.subagent_type = Some("explore".into());
            actor.forked_tool_override = Some(super::ToolSpecBundle::without_identity(snapshot.clone()));
            let (events, mut event_rx) = tokio::sync::mpsc::unbounded_channel();
            actor.sampler_handle = xai_grok_sampler::SamplerActor::spawn(
                actor.turn_sampler_config_from_binding(&fixture.binding).await,
                xai_grok_sampler::RetryPolicy { max_retries: 0, ..Default::default() }, events,
            );
            actor.workspace_ops.bind_local_session(
                &actor.session_id_string(), actor.tool_context.cwd.as_path().to_path_buf(),
                actor.tool_context.hunk_tracker_handle.clone(), actor.agent.borrow().tool_bridge().toolset(), None,
            ).unwrap();
            OUTER_BOUND_TRACE.with(|trace| {
                assert!(trace.borrow().is_none());
                *trace.borrow_mut() = Some(OuterBoundTrace { install_after_first: None, builds: Vec::new() });
            });
            let _guard = OuterBoundGuard;
            let drainer = fixture.actor.clone();
            let drain = tokio::task::spawn_local(async move {
                while let Some(event) = event_rx.recv().await { drainer.handle_sampling_event(event).await; }
            });
            let mut salvage = super::super::length_salvage::LengthSalvage::new(None);
            let mut sampling = Default::default();
            let outcome = tokio::time::timeout(std::time::Duration::from_secs(300),
                fixture.actor.process_conversation_turn_with_recovery(
                    "parent-lifecycle-refusal", None, None, None, &mut salvage, &mut sampling,
                ),
            ).await.expect("actual fork lifecycle turn completes");
            drain.abort();
            let _ = drain.await;
            assert!(matches!(&outcome, Ok(crate::session::acp_session::TurnOutcome::Completed { .. })), "parent fork lifecycle must complete: {:?}", outcome.err());
            let builds = OUTER_BOUND_TRACE.with(|trace| std::mem::take(&mut trace.borrow_mut().as_mut().unwrap().builds));
            assert_eq!(builds.len(), 1, "one actual bound fork build");
            let (request, binding) = &builds[0];
            assert_binding_eq(binding, &fixture.binding);
            assert_eq!(serde_json::to_value(&request.tools).unwrap(), serde_json::to_value(&snapshot).unwrap());
            assert_eq!(serde_json::to_value(&fixture.actor.forked_tool_override.as_ref().unwrap().specs).unwrap(), serde_json::to_value(&snapshot).unwrap());
            assert!(fixture.live_wire.exchanges.borrow().is_empty());
            let exchanges = fixture.wire.exchanges.borrow();
            assert_eq!(exchanges.len(), 1);
            assert_eq!(exchanges[0].path, "/v1/messages");
            assert_eq!(exchanges[0].parsed_body["model"], binding.config.model);
            parent_golden_record(&format!("lifecycle-refusals/{registration}"), serde_json::json!({"frozen":{
                "reason":null, "category":"submitted", "submission_count":exchanges.len(),
                "bodies":exchanges.iter().map(|exchange| serde_json::json!({"raw_body":String::from_utf8(exchange.raw_body.clone()).unwrap(),"parsed_body":exchange.parsed_body})).collect::<Vec<_>>(),
                "input_history":fixture.history, "selected_specs":request.tools, "admission":request.search_admission.map(|a| serde_json::json!({"supports_search_tool":a.supports_search_tool,"has_searchable_tools":a.has_searchable_tools})),
                "replay_plan":"absent in parent carrier",
            }, "provenance": {
                "binding_config":{"model":binding.config.model,"base_url":binding.config.base_url,"api_backend":binding.config.api_backend,"supports_search_tool":binding.config.supports_search_tool},
                "configured_row_id":fixture.actor.models_manager.current_model_id().0,
                "binding_observation":"actual OUTER_BOUND_TRACE build returned by process_conversation_turn_with_recovery",
                "backend":binding.config.api_backend, "dialect":"Messages from captured binding and /v1/messages",
                "snapshot_entry":"actual run_session SessionCommand::SnapshotToolDefinitions reply",
                "child_entry":"process_conversation_turn_with_recovery through turn bound-build/projection seam",
                "parent_snapshot":snapshot, "parent_registry":parent_registry,
                "child_registry":parent_golden_registry(&fixture.actor),
                "request_items":request.items, "selected_hosted_tools":format!("{:?}", request.hosted_tools),
                "selected_specs_observation":"actual bound request; exact survivor order/schema/exposure equals the real parent snapshot",
                "header_flags":exchanges.iter().map(|exchange| &exchange.headers).collect::<Vec<_>>(),
                "exchanges":exchanges.iter().enumerate().map(|(sequence, exchange)| serde_json::json!({"listener_sequence":sequence,"path":exchange.path,"request_id":exchange.request_id,"response_id":"parent-capture-response","response_body":exchange.response_body,"headers":exchange.headers})).collect::<Vec<_>>(),
                "normalization_mapping":[],
            }}));
        }
        a4_lifecycle_companion_scenarios().await;
    }).await;
}

#[tokio::test(flavor = "current_thread")]
async fn interim_messages_discovery_compaction_lifecycle() {
    const NAME: &str = "session::acp_session::sampler_turn::tests::interim_messages_discovery_compaction_lifecycle";
    if parent_golden_isolated(NAME) {
        return;
    }
    tokio::task::LocalSet::new().run_until(async {
        for surface in ["two-pass", "full", "remote"] {
            let backend = if surface == "remote" { ApiBackend::Responses } else { ApiBackend::Messages };
            let mut fixture = parent_golden_fixture(backend).await;
            fixture.binding.config.model = if surface == "remote" { "r12-compact-remote" } else { "r12-compact" }.into();
            fixture.actor.chat_state_handle.install_transport_binding(fixture.binding.clone()).await.unwrap();
            let actor = std::sync::Arc::get_mut(&mut fixture.actor).unwrap();
            actor.compaction.compaction_mode = xai_chat_state::CompactionMode::Summary;
            actor.compaction.verbatim_input = true;
            {
                let mut slot = actor.agent.borrow_mut();
                let agent = &*slot;
                let mut policy = agent.compaction_policy().clone();
                policy.two_pass_enabled = surface == "two-pass";
                policy.remote_compaction_v2 = surface == "remote";
                policy.memory_flush_enabled = false;
                policy.wall_clock_budget_secs = 30;
                *slot = xai_grok_agent::Agent::new(
                    agent.definition().clone(), agent.prompt_context().clone(), agent.system_prompt().to_string(),
                    agent.tool_bridge().clone(), agent.reminder_policy().clone(), policy, Vec::new(), true,
                );
            }
            fixture.history.insert(1, ConversationItem::user("Earlier work. ".repeat(3000)));
            fixture.history.insert(2, ConversationItem::assistant("Earlier result. ".repeat(1800)));
            actor.chat_state_handle.replace_conversation(fixture.history.clone());
            if surface == "remote" {
                let mut entry = support::entry_with_search_flag("r12-compact-remote", true);
                entry.info.model_family = Some("codex".into());
                actor.models_manager.insert_test_entry("r12-compact-remote", entry);
            }
            let definitions = actor.prepare_tool_definitions_inner().await;
            let (selected, token_kind, token_input, tool_tokens) = if surface == "two-pass" {
                let selected = actor.turn_base_tool_specs(&definitions);
                let tokens = xai_chat_state::estimate_tool_specs_tokens(&selected);
                let input = serde_json::to_value(&selected).unwrap();
                (selected, "specs", input, tokens)
            } else {
                let tokens = xai_chat_state::estimate_tool_definitions_tokens(&definitions);
                let input = serde_json::to_value(&definitions).unwrap();
                (definitions.into_iter().map(ToolSpec::from).collect(), "definitions", input, tokens)
            };
            assert!(selected.iter().any(|tool| tool.name == "search_tool"));
            assert!(!selected.iter().any(|tool| tool.name == "alpha__lookup" || tool.name == "zeta__fetch"));
            let mut prefire = serde_json::Value::Null;
            if surface == "two-pass" {
                assert!(fixture.actor.compaction.prefire.try_begin());
                fixture.actor.run_prefire_pass1().await;
                let cache = fixture.actor.compaction.prefire.take().expect("actual prefire creates NOTE1");
                prefire = serde_json::json!({"note1":cache.note1,"prefix_len":cache.prefix_len,"model":cache.model_slug});
                fixture.actor.compaction.prefire.store(cache);
            }
            let date_before = chrono::Local::now().format("%Y-%m-%d").to_string();
            let result = tokio::time::timeout(std::time::Duration::from_secs(300), fixture.actor.run_compact(None)).await.expect("actual compaction entry completes");
            let date_after = chrono::Local::now().format("%Y-%m-%d").to_string();
            assert!(result.is_ok(), "actual {surface} compaction failed: {:?}", result.err());
            let after = fixture.actor.chat_state_handle.get_conversation().await;
            let exchanges = fixture.wire.exchanges.borrow();
            assert_eq!(exchanges.len(), if surface == "two-pass" { 2 } else { 1 });
            for exchange in exchanges.iter() {
                let tools = exchange.parsed_body["tools"].as_array().unwrap();
                assert!(tools.iter().any(|tool| tool["name"] == "search_tool"));
                assert!(tools.iter().any(|tool| tool["name"] == "use_tool"));
                assert!(!tools.iter().any(|tool| tool["type"] == "tool_search_tool_bm25_20251119" || tool["type"] == "tool_search"), "compaction keeps its absent admission");
            }
            parent_golden_record(&format!("lifecycle-compaction/{surface}"), serde_json::json!({"frozen":{
                "input":fixture.history, "selected_specs":selected, "token_kind":token_kind,
                "token_input":token_input, "tool_tokens":tool_tokens, "prefire":prefire,
                "after":after, "admission":null,
                "bodies":exchanges.iter().map(|exchange| serde_json::json!({"raw_body":String::from_utf8(exchange.raw_body.clone()).unwrap(),"parsed_body":exchange.parsed_body})).collect::<Vec<_>>(),
            }, "environment":{"date_before":date_before,"date_after":date_after},
                "provenance":{"header_flags":exchanges.iter().map(|exchange| &exchange.headers).collect::<Vec<_>>()}
            }));
        }
    }).await;
}

fn identity_snapshot_handle(
    actor: &super::SessionActor,
    cmd_tx: tokio::sync::mpsc::UnboundedSender<crate::session::commands::SessionCommand>,
) -> crate::session::SessionHandle {
    crate::session::SessionHandle {
        cmd_tx,
        persistence_tx: tokio::sync::mpsc::unbounded_channel().0,
        registry_write_order: Default::default(),
        current_prompt_id: Default::default(),
        active_work: Default::default(),
        pending_interactions: Default::default(),
        info: actor.session_info.clone(),
        max_turns: None,
        resolved_tool_overrides: actor.resolved_tool_overrides.clone(),
        spawn_snapshot: crate::session::SpawnSnapshot {
            applied_tool_overrides: None,
            memory_mode: None,
        },
        hunk_tracker_handle: actor.tool_context.hunk_tracker_handle.clone(),
        chat_state_handle: actor.chat_state_handle.clone(),
        signals_handle: actor.signals_handle(),
        gateway_enabled: actor.notifications.gateway_enabled.clone(),
        emit_local_background_tasks: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true)),
        client_caps: crate::session::notifications::SessionClientCaps::new(false, true),
        mcp_servers: Vec::new(),
        initial_client_mcp_servers: Vec::new(),
        display_cwd: None,
        feedback_manager: actor.feedback_manager.clone(),
        upload_queue: Default::default(),
        upload_failures_since_success: Default::default(),
        tool_context: actor.tool_context.clone(),
        model_id: agent_client_protocol::ModelId::new("identity-parent"),
        reasoning_effort: None,
        yolo_mode: false,
        origin_client: None,
        code_nav_enabled: false,
        ask_user_question_enabled: true,
        non_interactive: false,
        plan_mode: actor.plan_mode.clone(),
        force_compact: actor.compaction.force_compact.clone(),
        permission_handle: xai_grok_workspace::permission::PermissionHandle::allow_all(),
        attribution_callback: None,
        agent_name: "identity-parent".into(),
        managed_mcp_proxy_base_url: String::new(),
        session_default_agent_profile: None,
        allowed_subagent_types: None,
        hook_registry: None,
        workspace_ops: actor.workspace_ops.clone(),
        terminal_backend: None,
        tools_notification_handle: None,
        scheduler_handle: None,
    }
}

fn assert_identity_coordinates(bundle: &super::ToolSpecBundle, expected: &[usize]) {
    assert_eq!(
        bundle
            .companion
            .as_ref()
            .map(|companion| companion.coordinates.as_slice()),
        Some(expected),
        "A1 exact survivor coordinates"
    );
    assert!(
        bundle.has_valid_identity(),
        "A1 coordinates bind the same source and exact surviving specs"
    );
}

#[test]
fn parent_bridge_companion_preserves_filtered_coordinates() {
    use xai_grok_tools::registry::types::ToolConfig;
    use xai_grok_tools::types::tool::{ToolKind, ToolNamespace};
    const NAME: &str = "session::acp_session::sampler_turn::tests::parent_bridge_companion_preserves_filtered_coordinates";
    if parent_golden_isolated(NAME) {
        return;
    }
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    let _runtime = runtime.enter();
    let local = tokio::task::LocalSet::new();
    let mut actor = local.block_on(&runtime, support::plain_actor());
    actor.agent.replace(local.block_on(&runtime, support::test_agent_with_tools(vec![
        ToolConfig::for_tool::<xai_grok_tools::implementations::grok_build::send_subagent_message::SendSubagentMessageTool>().with_name("parent_root_only"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::search_tool::SearchTool>().with_name("bridge__discover"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::use_tool::UseTool>().with_name("bridge__invoke"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::grok_build::read_file::ReadFileTool>().with_name("search_tool"),
    ])));
    for (name, namespace, kind) in [
        (
            "ask_user_question",
            ToolNamespace::GrokBuild,
            ToolKind::Other,
        ),
        ("workflow", ToolNamespace::GrokBuild, ToolKind::Workflow),
        (
            "builtin__ordinary",
            ToolNamespace::GrokBuild,
            ToolKind::Other,
        ),
        ("zeta__fetch", ToolNamespace::MCP, ToolKind::Other),
        ("alpha__lookup", ToolNamespace::MCP, ToolKind::Other),
        (
            xai_grok_tools::implementations::grok_build::V2_COLLABORATION_TOOL_NAMES[0],
            ToolNamespace::GrokBuild,
            ToolKind::ActiveAgentMessage,
        ),
    ] {
        parent_golden_register(&actor, name, namespace, kind);
    }
    let (manager, _home) = support::manager_with_entries();
    manager.insert_test_entry(
        "identity-parent",
        support::entry_with_deferred_tools("identity-parent", true, &["bridge__invoke"]),
    );
    manager.set_current_model_id(agent_client_protocol::ModelId::new("identity-parent"));
    actor.models_manager = manager;
    let bridge = actor.agent.borrow().tool_bridge().clone();
    let inventory = bridge.tools_with_identity();
    assert_eq!(
        inventory
            .iter()
            .map(|(definition, _, _)| definition.function.name.as_str())
            .collect::<Vec<_>>(),
        vec![
            "parent_root_only",
            "bridge__discover",
            "bridge__invoke",
            "search_tool",
            "ask_user_question",
            "workflow",
            "builtin__ordinary",
            "zeta__fetch",
            "alpha__lookup",
            xai_grok_tools::implementations::grok_build::V2_COLLABORATION_TOOL_NAMES[0],
        ]
    );
    let (events, event_rx) = tokio::sync::mpsc::unbounded_channel();
    actor.event_tx = events;
    let actor = std::sync::Arc::new(actor);
    let (commands, command_rx) = tokio::sync::mpsc::unbounded_channel();
    let (_chat, chat_rx) = tokio::sync::mpsc::unbounded_channel();
    let handle = identity_snapshot_handle(&actor, commands);
    let task = local.block_on(&runtime, async {
        tokio_util::task::AbortOnDropHandle::new(tokio::task::spawn_local(
            super::super::run_session(
                actor.clone(),
                command_rx,
                chat_rx,
                event_rx,
                None,
                std::sync::Arc::new(parking_lot::Mutex::new(
                    xai_grok_workspace::file_system::CodebaseIndexManager::new(),
                )),
                actor.tool_context.cwd.as_path().to_path_buf(),
                crate::session::fs_watch::FsWatchCapabilities::none(),
            ),
        ))
    });
    let legacy = local
        .block_on(
            &runtime,
            tokio::time::timeout(
                std::time::Duration::from_secs(30),
                handle.snapshot_tool_definitions(),
            ),
        )
        .unwrap();
    let snapshot = local
        .block_on(
            &runtime,
            tokio::time::timeout(
                std::time::Duration::from_secs(30),
                handle.snapshot_tool_definitions_with_identity(),
            ),
        )
        .unwrap();
    assert_native_specs(
        &snapshot.specs,
        &legacy,
        "A1 additive snapshot retains the legacy bare vector",
    );
    assert_identity_coordinates(&snapshot, &[1, 2, 3, 4, 5, 6, 9]);
    assert_eq!(
        snapshot.companion.as_ref().unwrap().inventory[1].2,
        ToolKind::SearchTool
    );
    assert_eq!(
        snapshot.companion.as_ref().unwrap().inventory[2].2,
        ToolKind::UseTool
    );
    assert_eq!(
        snapshot.companion.as_ref().unwrap().inventory[3].2,
        ToolKind::Read
    );
    assert_eq!(snapshot.specs[1].exposure, ToolExposure::Deferred);
    assert!(actor.plan_mode.lock().activate_from_tool());
    let in_plan = local.block_on(&runtime, handle.snapshot_tool_definitions_with_identity());
    assert_native_specs(
        &in_plan.specs,
        &legacy,
        "A1 plan filtering preserves the same parent specs",
    );
    assert_identity_coordinates(&in_plan, &[1, 2, 3, 4, 5, 6, 9]);
    let inherited = snapshot.clone().filter_for_subagent();
    let mut expected = legacy.clone();
    crate::agent::subagent::strip_ask_user_question_tool(&mut expected);
    crate::agent::subagent::strip_workflow_tool(&mut expected);
    assert_native_specs(
        &inherited.specs,
        &expected,
        "A1 spawn filters preserve exact survivor specs and order",
    );
    assert_identity_coordinates(&inherited, &[1, 2, 3, 6, 9]);
    assert!(std::sync::Arc::ptr_eq(
        &snapshot.companion.as_ref().unwrap().inventory,
        &inherited.companion.as_ref().unwrap().inventory
    ));
    for unrelated_registration in [false, true] {
        let mut child = local.block_on(&runtime, support::plain_actor());
        child
            .agent
            .replace(local.block_on(&runtime, support::test_agent_with_tools(Vec::new())));
        if unrelated_registration {
            for name in ["bridge__discover", "bridge__invoke"] {
                parent_golden_register(&child, name, ToolNamespace::GrokBuild, ToolKind::Other);
            }
        }
        child.startup_hints.is_subagent = true;
        child.forked_tool_override = Some(inherited.clone());
        let mut config = local
            .block_on(
                &runtime,
                child.chat_state_handle.capture_transport_binding(),
            )
            .unwrap()
            .config;
        for backend in [
            ApiBackend::Responses,
            ApiBackend::Messages,
            ApiBackend::ChatCompletions,
        ] {
            config.api_backend = backend;
            config.supports_search_tool = true;
            let selected = child
                .tool_candidates_for_turn(
                    NativeToolCandidates::builtins_only(vec![ToolSpec {
                        name: "child__not_in_parent".into(),
                        description: None,
                        parameters: serde_json::json!({"type":"object"}),
                        exposure: ToolExposure::Immediate,
                    }]),
                    None,
                )
                .select_for_row(&config);
            assert_native_specs(
                &selected,
                &expected,
                "A1 real fork consumer retains parent specs and empty MCP membership",
            );
            assert_identity_coordinates(
                child.forked_tool_override.as_ref().unwrap(),
                &[1, 2, 3, 6, 9],
            );
        }
    }
    let mut stale = inherited.clone();
    stale.companion = in_plan.filter_for_subagent().companion;
    assert!(
        !stale.has_valid_identity(),
        "a companion from another snapshot cannot bind equal specs"
    );
    let replaced = inherited.clone().filter_specs(|specs| {
        if specs[0].name == "bridge__discover" {
            specs[0].parameters = serde_json::json!({"type":"object","properties":{"replacement":{"type":"boolean"}}});
        }
    });
    assert!(
        replaced.companion.is_none(),
        "no removed identity rebounds onto a same-named replacement"
    );
    assert_native_specs(
        &inherited.specs,
        &expected,
        "filtering never mutates the parent carrier",
    );
    let missing = super::ToolSpecBundle::without_identity(expected.clone());
    assert!(!missing.has_valid_identity());
    assert_native_specs(
        &missing.specs,
        &expected,
        "companion-less compatibility retains the same bare specs",
    );

    let (reached, reached_rx) = tokio::sync::oneshot::channel();
    let (resume, resume_rx) = tokio::sync::oneshot::channel();
    let _trace = trace_native_snapshots(Some((reached, resume_rx)));
    let mutate = futures::FutureExt::map(reached_rx, |_| {
        assert!(bridge.toolset().unregister_tool_by_name("bridge__discover"));
        register_native_fixture(
            &actor,
            "bridge__discover",
            ToolNamespace::GrokBuild,
            "replacement unrelated tool",
            serde_json::json!({"type":"object","properties":{"replacement":{"type":"integer"}}}),
        );
        resume.send(()).unwrap();
    });
    let ((prepared, _), ()) = local.block_on(
        &runtime,
        futures::future::join(actor.prepare_native_tool_candidates_timed(), mutate),
    );
    let prepared_bundle = actor.prepared_tool_bundle(&prepared);
    assert_identity_coordinates(&prepared_bundle, &[0, 1, 2, 3, 4, 5, 6, 9, 8, 7]);
    assert_eq!(
        prepared_bundle.companion.as_ref().unwrap().inventory[1].2,
        ToolKind::SearchTool,
        "A1 prepared identity is from the captured inventory, never a second live lookup"
    );
    assert_eq!(bridge.tool_kind("bridge__discover"), Some(ToolKind::Other));
    assert_eq!(prepared.mcp_coordinates, vec![8, 7]);
    assert_eq!(
        prepared
            .mcp_specs
            .iter()
            .map(|spec| spec.name.as_str())
            .collect::<Vec<_>>(),
        vec!["alpha__lookup", "zeta__fetch"]
    );
    assert_eq!(observed_native_snapshots().len(), 1);
    assert_identity_coordinates(&inherited, &[1, 2, 3, 6, 9]);
    assert_native_specs(
        &inherited.specs,
        &expected,
        "later registry replacement cannot rewrite a parent bundle",
    );

    task.abort();
    let _ = local.block_on(&runtime, task);
    assert!(
        local
            .block_on(&runtime, handle.snapshot_tool_definitions())
            .is_empty(),
        "legacy dead actor remains empty"
    );
    let gone = local.block_on(&runtime, handle.snapshot_tool_definitions_with_identity());
    assert!(gone.specs.is_empty() && gone.companion.is_none());
    for paired in [false, true] {
        let (commands, mut replies) = tokio::sync::mpsc::unbounded_channel();
        let dropped = identity_snapshot_handle(&actor, commands);
        if paired {
            let future = dropped.snapshot_tool_definitions_with_identity();
            match replies.try_recv().unwrap() {
                crate::session::commands::SessionCommand::SnapshotToolDefinitionsWithIdentity {
                    respond_to,
                } => drop(respond_to),
                _ => panic!("expected paired snapshot command"),
            }
            let empty = local.block_on(&runtime, future);
            assert!(empty.specs.is_empty() && empty.companion.is_none());
        } else {
            let discard =
                futures::FutureExt::map(replies.recv(), |command| match command.unwrap() {
                    crate::session::commands::SessionCommand::SnapshotToolDefinitions {
                        respond_to,
                    } => drop(respond_to),
                    _ => panic!("expected legacy snapshot command"),
                });
            let (empty, ()) = local.block_on(
                &runtime,
                futures::future::join(dropped.snapshot_tool_definitions(), discard),
            );
            assert!(empty.is_empty(), "legacy dropped reply remains empty");
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum A2Inventory {
    Mixed,
    BridgeOnly,
    BridgeLess,
    Empty,
}

async fn a2_projection_fixture(
    backend: &ApiBackend,
    flag: bool,
    family: &str,
    inventory: A2Inventory,
    wire: &ParentGoldenWire,
) -> NativeCandidateFixture {
    use xai_grok_tools::registry::types::ToolConfig;
    let mut fixture = native_candidate_fixture(backend, flag, &[]).await;
    let actor = &mut fixture.actor;
    let tools = match inventory {
        A2Inventory::Mixed | A2Inventory::BridgeOnly => vec![
            ToolConfig::for_tool::<xai_grok_tools::implementations::search_tool::SearchTool>()
                .with_name("bridge__discover"),
            ToolConfig::for_tool::<xai_grok_tools::implementations::use_tool::UseTool>()
                .with_name("bridge__invoke"),
        ],
        A2Inventory::BridgeLess | A2Inventory::Empty => Vec::new(),
    };
    actor
        .agent
        .replace(support::test_agent_with_tools(tools).await);
    if matches!(inventory, A2Inventory::Mixed | A2Inventory::BridgeLess) {
        register_native_builtins(actor);
        register_native_pair(actor);
        for name in ["search_tool", "use_tool"] {
            register_native_fixture(
                actor,
                name,
                ToolNamespace::GrokBuild,
                "Unrelated exact-name builtin",
                native_alpha_schema(),
            );
        }
    }
    let mut entry = support::entry_with_deferred_tools(
        "a2-bound",
        flag,
        &["bridge__invoke", "builtin__renamed"],
    );
    entry.info.model_family = Some(family.into());
    actor.models_manager.insert_test_entry("a2-bound", entry);
    actor
        .models_manager
        .set_current_model_id(agent_client_protocol::ModelId::new("a2-bound"));
    let mut binding = actor
        .chat_state_handle
        .capture_transport_binding()
        .await
        .unwrap();
    binding.config.model = "a2-bound".into();
    binding.config.api_backend = backend.clone();
    binding.config.base_url = wire.url.clone();
    binding.config.supports_search_tool = flag;
    actor
        .chat_state_handle
        .install_transport_binding(binding)
        .await
        .unwrap();
    actor.max_retries = 0;
    fixture
}

async fn a2_build_projection_request(
    actor: &super::SessionActor,
    projection: &super::BridgeDeclarationProjection,
) -> (ConversationRequest, RequestTransportBinding) {
    actor
        .chat_state_handle
        .build_request_with_binding(
            projection.candidates(),
            None,
            false,
            None,
            "a2-conversation".into(),
            "a2-request".into(),
        )
        .await
        .unwrap()
}

async fn a2_received_body(
    actor: &super::SessionActor,
    request: &ConversationRequest,
    binding: &RequestTransportBinding,
    wire: &ParentGoldenWire,
    family: &str,
) -> ParentGoldenExchange {
    let config = actor.turn_sampler_config_from_binding(binding).await;
    assert_eq!(
        config.model_family.as_deref(),
        Some(family),
        "A2 lowering uses the captured model family"
    );
    assert_eq!(config.api_backend, binding.config.api_backend);
    assert_eq!(config.base_url, binding.config.base_url);
    assert!(
        config.bearer_resolver.is_none(),
        "API-key fixture never resolves session auth"
    );
    let client = xai_grok_sampler::SamplingClient::new(config).unwrap();
    let count = wire.exchanges.borrow().len();
    match binding.config.api_backend {
        ApiBackend::Responses => {
            let (stream, _, _) = client
                .conversation_stream_responses(request.clone(), &mut None)
                .await
                .unwrap();
            let events: Vec<_> = futures::TryStreamExt::try_collect(stream).await.unwrap();
            assert!(!events.is_empty());
        }
        ApiBackend::Messages => {
            let (stream, _) = client
                .conversation_stream_messages(request.clone())
                .await
                .unwrap();
            let events: Vec<_> = futures::TryStreamExt::try_collect(stream).await.unwrap();
            assert!(!events.is_empty());
        }
        ApiBackend::ChatCompletions => {
            unreachable!("Chat preservation uses its ordinary serializer")
        }
    }
    let exchanges = wire.exchanges.borrow();
    assert_eq!(
        exchanges.len(),
        count + 1,
        "A2 exactly one loopback request per lowering"
    );
    let exchange = exchanges.last().unwrap().clone();
    assert_eq!(
        serde_json::from_slice::<serde_json::Value>(&exchange.raw_body).unwrap(),
        exchange.parsed_body
    );
    assert_eq!(exchange.parsed_body["model"], binding.config.model);
    if binding.config.api_backend == ApiBackend::Responses {
        assert_eq!(exchange.parsed_body["store"], false);
    }
    exchange
}

fn a2_assert_one_bound_build(
    events: &mut tokio::sync::mpsc::UnboundedReceiver<xai_chat_state::ChatStateEvent>,
) {
    let mut builds = 0;
    while let Ok(event) = events.try_recv() {
        if matches!(event, xai_chat_state::ChatStateEvent::ImageBudget { .. }) {
            builds += 1;
        }
    }
    assert_eq!(
        builds, 1,
        "A2 one image-budget observation proves one actor build"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn responses_projection_uses_bound_admission_and_typed_identity() {
    const NAME: &str = "session::acp_session::sampler_turn::tests::responses_projection_uses_bound_admission_and_typed_identity";
    if parent_golden_isolated(NAME) {
        return;
    }
    tokio::task::LocalSet::new().run_until(async {
        for (family, backend, flag, admission, inventory) in [
            ("xai", ApiBackend::Responses, true, "built", A2Inventory::Mixed),
            ("codex", ApiBackend::Responses, true, "built", A2Inventory::Mixed),
            ("xai", ApiBackend::Responses, false, "built", A2Inventory::Mixed),
            ("xai", ApiBackend::Responses, true, "absent", A2Inventory::Mixed),
            ("xai", ApiBackend::Responses, true, "surface-false", A2Inventory::Mixed),
            ("xai", ApiBackend::ChatCompletions, true, "manual-true", A2Inventory::Mixed),
            ("xai", ApiBackend::Messages, true, "built", A2Inventory::Mixed),
            ("xai", ApiBackend::Messages, false, "built", A2Inventory::Mixed),
            ("xai", ApiBackend::Responses, true, "built", A2Inventory::BridgeOnly),
            ("xai", ApiBackend::Responses, true, "built", A2Inventory::BridgeLess),
            ("xai", ApiBackend::Responses, true, "built", A2Inventory::Empty),
        ] {
            let wire = ParentGoldenWire::start().await;
            let mut fixture = a2_projection_fixture(&backend, flag, family, inventory, &wire).await;
            let actor = &fixture.actor;
            let _snapshot = trace_native_snapshots(None);
            let (prepared, _) = actor.prepare_native_tool_candidates_timed().await;
            let bundle = actor.prepared_tool_bundle(&prepared);
            assert!(bundle.has_valid_identity());
            let input_specs = bundle.specs.clone();
            let mut projection = super::BridgeDeclarationProjection::prepared(
                bundle,
                prepared.mcp_specs.iter().map(|spec| spec.name.clone()).collect(),
            );
            if matches!(inventory, A2Inventory::Mixed) {
                projection.append_builtin(child_structured_output_spec());
            }
            let (mut request, binding) = a2_build_projection_request(actor, &projection).await;
            assert_eq!(request.model.as_deref(), Some(binding.config.model.as_str()));
            assert_eq!(request.search_admission.unwrap().supports_search_tool, flag);
            match admission {
                "absent" => request.search_admission = None,
                "surface-false" => request.search_admission = Some(xai_grok_sampling_types::SearchAdmission { supports_search_tool: true, has_searchable_tools: false }),
                "manual-true" => request.search_admission = Some(xai_grok_sampling_types::SearchAdmission { supports_search_tool: true, has_searchable_tools: true }),
                "built" => {},
                _ => unreachable!(),
            }
            if matches!(inventory, A2Inventory::Mixed) {
                request.hosted_tools = vec![xai_grok_sampling_types::HostedTool::WebSearch { options: None }];
            }
            let original_admission = request.search_admission;
            let eligible = backend == ApiBackend::Responses && original_admission.is_some_and(xai_grok_sampling_types::SearchAdmission::admitted);
            let original = request.clone();
            let mut live = binding.clone();
            live.config.model = "a2-other".into();
            live.config.api_backend = if backend == ApiBackend::Responses { ApiBackend::Messages } else { ApiBackend::Responses };
            live.config.supports_search_tool = !flag;
            live.config.base_url = "http://127.0.0.1:1/v1".into();
            live.credentials.api_key = Some("a2-other-fixture-key".into());
            let mut other = support::entry_with_deferred_tools("a2-other", !flag, &[]);
            other.info.model_family = Some(if family == "codex" { "xai" } else { "codex" }.into());
            actor.models_manager.insert_test_entry("a2-other", other);
            actor.models_manager.set_current_model_id(agent_client_protocol::ModelId::new("a2-other"));
            actor.chat_state_handle.install_transport_binding(live.clone()).await.unwrap();
            actor.project_bound_bridge_declarations(&mut request, &binding, &projection).unwrap();
            if backend == ApiBackend::ChatCompletions {
                assert_eq!(native_lowered_body(&request, &backend), native_lowered_body(&original, &backend), "A2 unsupported Chat admission keeps the full parent body");
            } else {
                let before = a2_received_body(actor, &original, &binding, &wire, family).await;
                let after = a2_received_body(actor, &request, &binding, &wire, family).await;
                if backend == ApiBackend::Responses {
                    let native: Vec<_> = after.parsed_body["tools"].as_array().into_iter().flatten().filter(|tool| tool["type"] == "tool_search").collect();
                    assert_eq!(native.len(), usize::from(original_admission.is_some_and(xai_grok_sampling_types::SearchAdmission::admitted)), "A2 independent native search survives projection, including bridge-only input: {inventory:?}");
                    for tool in native { assert_eq!(tool["execution"], "client"); }
                }
                let mut expected = before.parsed_body.clone();
                if eligible {
                    expected["tools"].as_array_mut().unwrap().retain(|tool| !(tool["type"] == "function" && ["bridge__discover", "bridge__invoke"].contains(&tool["name"].as_str().unwrap_or_default())));
                }
                assert_eq!(after.parsed_body["tools"], expected["tools"], "A2 typed Responses declarations: {backend:?} {admission} {inventory:?}");
                assert_eq!(after.parsed_body, expected, "A2 full body changes only selected typed bridge declarations");
                if !eligible { assert_eq!(after.raw_body, before.raw_body, "A2 unadmitted/interim full encoded parent bytes"); }
            }
            let expected_specs: Vec<_> = original.tools.iter().filter(|spec| !eligible || !["bridge__discover", "bridge__invoke"].contains(&spec.name.as_str())).cloned().collect();
            assert_native_specs(&request.tools, &expected_specs, "A2 exact remaining order/schema/exposure");
            assert_eq!(request.search_admission, original_admission, "A2 original admission is never recomputed");
            assert_native_specs(&projection.bundle.specs, &input_specs, "A2 projection never mutates its input snapshot");
            assert_eq!(observed_native_snapshots().len(), 1, "A2 prepare once, never refresh after bound build");
            assert_binding_eq(&actor.chat_state_handle.capture_transport_binding().await.unwrap(), &live);
            if matches!(inventory, A2Inventory::BridgeOnly) { assert!(request.tools.is_empty()); assert!(request.search_admission.unwrap().admitted()); }
            if matches!(inventory, A2Inventory::Empty) { assert!(!request.search_admission.unwrap().admitted()); }
            if matches!(inventory, A2Inventory::Mixed | A2Inventory::BridgeLess) {
                for name in ["search_tool", "use_tool", "builtin__renamed"] { assert!(request.tools.iter().any(|spec| spec.name == name)); }
                let mcp: Vec<_> = request.tools.iter().filter(|spec| ["alpha__lookup", "zeta__fetch"].contains(&spec.name.as_str())).cloned().collect();
                assert_native_specs(&mcp, &if backend == ApiBackend::Messages && flag { native_selected_mcp(&prepared.mcp_specs) } else { Vec::new() }, "A2 inherited typed MCP selection is unchanged");
            }
            a2_assert_one_bound_build(&mut fixture.events);
        }
    }).await;
}

async fn a2_parent_bridge_snapshots() -> (super::ToolSpecBundle, super::ToolSpecBundle) {
    use xai_grok_tools::registry::types::ToolConfig;
    use xai_grok_tools::types::tool::ToolKind;
    let mut actor = support::plain_actor().await;
    actor.agent.replace(support::test_agent_with_tools(vec![
        ToolConfig::for_tool::<xai_grok_tools::implementations::grok_build::send_subagent_message::SendSubagentMessageTool>().with_name("parent_root_only"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::search_tool::SearchTool>().with_name("bridge__discover"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::use_tool::UseTool>().with_name("bridge__invoke"),
        ToolConfig::for_tool::<xai_grok_tools::implementations::grok_build::read_file::ReadFileTool>().with_name("search_tool"),
    ]).await);
    for (name, namespace, kind) in [
        (
            "ask_user_question",
            ToolNamespace::GrokBuild,
            ToolKind::Other,
        ),
        ("workflow", ToolNamespace::GrokBuild, ToolKind::Workflow),
        (
            "builtin__ordinary",
            ToolNamespace::GrokBuild,
            ToolKind::Other,
        ),
        ("alpha__lookup", ToolNamespace::MCP, ToolKind::Other),
    ] {
        parent_golden_register(&actor, name, namespace, kind);
    }
    let (manager, _home) = support::manager_with_entries();
    manager.insert_test_entry(
        "a2-parent",
        support::entry_with_deferred_tools("a2-parent", true, &["bridge__invoke"]),
    );
    manager.set_current_model_id(agent_client_protocol::ModelId::new("a2-parent"));
    actor.models_manager = manager;
    let (events, event_rx) = tokio::sync::mpsc::unbounded_channel();
    actor.event_tx = events;
    let actor = std::sync::Arc::new(actor);
    let (commands, command_rx) = tokio::sync::mpsc::unbounded_channel();
    let (_chat, chat_rx) = tokio::sync::mpsc::unbounded_channel();
    let handle = identity_snapshot_handle(&actor, commands);
    let task = tokio_util::task::AbortOnDropHandle::new(tokio::task::spawn_local(
        super::super::run_session(
            actor.clone(),
            command_rx,
            chat_rx,
            event_rx,
            None,
            std::sync::Arc::new(parking_lot::Mutex::new(
                xai_grok_workspace::file_system::CodebaseIndexManager::new(),
            )),
            actor.tool_context.cwd.as_path().to_path_buf(),
            crate::session::fs_watch::FsWatchCapabilities::none(),
        ),
    ));
    let legacy = handle.snapshot_tool_definitions().await;
    let first = handle.snapshot_tool_definitions_with_identity().await;
    let second = handle.snapshot_tool_definitions_with_identity().await;
    assert_native_specs(
        &first.specs,
        &legacy,
        "A2 real paired parent reply retains the bare legacy snapshot",
    );
    assert_identity_coordinates(&first, &[1, 2, 3, 4, 5, 6]);
    let first = first.filter_for_subagent();
    let second = second.filter_for_subagent();
    assert_identity_coordinates(&first, &[1, 2, 3, 6]);
    assert_eq!(first.specs[1].exposure, ToolExposure::Deferred);
    assert!(first.specs.iter().all(|spec| spec.name != "alpha__lookup"));
    task.abort();
    let _ = task.await;
    (first, second)
}

async fn a2_build_fork_request(
    actor: &super::SessionActor,
    projection: &super::BridgeDeclarationProjection,
) -> (ConversationRequest, RequestTransportBinding) {
    actor
        .chat_state_handle
        .build_request_with_binding(
            actor.tool_candidates_for_turn(
                projection.candidates(),
                Some(child_structured_output_spec().parameters),
            ),
            None,
            false,
            None,
            "a2-fork-conversation".into(),
            "a2-fork-request".into(),
        )
        .await
        .unwrap()
}

#[tokio::test(flavor = "current_thread")]
async fn responses_fork_projection_uses_parent_provenance() {
    use xai_grok_tools::registry::types::ToolConfig;
    use xai_grok_tools::types::tool::ToolKind;
    const NAME: &str = "session::acp_session::sampler_turn::tests::responses_fork_projection_uses_parent_provenance";
    if parent_golden_isolated(NAME) {
        return;
    }
    tokio::task::LocalSet::new().run_until(async {
        let (snapshot, other_snapshot) = a2_parent_bridge_snapshots().await;
        let parent_specs = snapshot.specs.clone();
        for registration in ["missing", "unrelated", "matching"] {
            let wire = ParentGoldenWire::start().await;
            let mut fixture = a2_projection_fixture(&ApiBackend::Responses, true, "codex", A2Inventory::Empty, &wire).await;
            let child = &mut fixture.actor;
            match registration {
                "missing" => {},
                "unrelated" => for name in ["bridge__discover", "bridge__invoke"] { parent_golden_register(child, name, ToolNamespace::GrokBuild, ToolKind::Other); },
                "matching" => { child.agent.replace(support::test_agent_with_tools(vec![
                    ToolConfig::for_tool::<xai_grok_tools::implementations::search_tool::SearchTool>().with_name("bridge__discover"),
                    ToolConfig::for_tool::<xai_grok_tools::implementations::use_tool::UseTool>().with_name("bridge__invoke"),
                ]).await); },
                _ => unreachable!(),
            }
            parent_golden_register(child, "child__not_in_parent", ToolNamespace::GrokBuild, ToolKind::Other);
            parent_golden_register(child, "child__lookup", ToolNamespace::MCP, ToolKind::Other);
            child.startup_hints.is_subagent = true;
            child.forked_tool_override = Some(snapshot.clone());
            let mut projection = super::BridgeDeclarationProjection::fork(child.forked_tool_override.as_ref().unwrap().clone());
            projection.append_builtin(child_structured_output_spec());
            assert!(projection.mcp_membership.is_empty());
            let (mut request, binding) = a2_build_fork_request(child, &projection).await;
            let mut original_specs = parent_specs.clone();
            original_specs.push(child_structured_output_spec());
            assert_native_specs(&request.tools, &original_specs, "A2 actual fork consumer preserves the authoritative parent vector and empty MCP membership");
            let original = request.clone();
            child.project_bound_bridge_declarations(&mut request, &binding, &projection).unwrap();
            let before = a2_received_body(child, &original, &binding, &wire, "codex").await;
            let after = a2_received_body(child, &request, &binding, &wire, "codex").await;
            let mut expected_body = before.parsed_body.clone();
            expected_body["tools"].as_array_mut().unwrap().retain(|tool| !(tool["type"] == "function" && ["bridge__discover", "bridge__invoke"].contains(&tool["name"].as_str().unwrap_or_default())));
            assert_eq!(after.parsed_body["tools"], expected_body["tools"], "A2 parent provenance removes only parent bridge identities: {registration}");
            assert_eq!(after.parsed_body, expected_body, "A2 fork full body retains all other members");
            let expected_specs: Vec<_> = original_specs.into_iter().filter(|spec| !["bridge__discover", "bridge__invoke"].contains(&spec.name.as_str())).collect();
            assert_native_specs(&request.tools, &expected_specs, "A2 no child registry union or unrelated-name removal");
            assert_eq!(request.search_admission, original.search_admission);
            assert_native_specs(&child.forked_tool_override.as_ref().unwrap().specs, &parent_specs, "A2 parent input unchanged in memory");
            assert_identity_coordinates(child.forked_tool_override.as_ref().unwrap(), &[1, 2, 3, 6]);
            a2_assert_one_bound_build(&mut fixture.events);
        }
        for state in ["missing", "stale", "mismatched"] {
            let mut invalid = snapshot.clone();
            match state {
                "missing" => invalid.companion = None,
                "stale" => invalid.companion = other_snapshot.companion.clone(),
                "mismatched" => invalid.specs[0].parameters = serde_json::json!({"type":"object","properties":{"replacement":{"type":"integer"}}}),
                _ => unreachable!(),
            }
            assert!(!invalid.has_valid_identity());
            for (backend, flag) in [(ApiBackend::Responses, true), (ApiBackend::Responses, false), (ApiBackend::Messages, true), (ApiBackend::ChatCompletions, true)] {
                let wire = ParentGoldenWire::start().await;
                let mut fixture = a2_projection_fixture(&backend, flag, "xai", A2Inventory::Empty, &wire).await;
                let child = &mut fixture.actor;
                child.startup_hints.is_subagent = true;
                child.forked_tool_override = Some(invalid.clone());
                parent_golden_register(child, "child__lookup", ToolNamespace::MCP, ToolKind::Other);
                let mut projection = super::BridgeDeclarationProjection::fork(child.forked_tool_override.as_ref().unwrap().clone());
                projection.append_builtin(child_structured_output_spec());
                let (mut request, binding) = a2_build_fork_request(child, &projection).await;
                let original = request.clone();
                let result = child.project_bound_bridge_declarations(&mut request, &binding, &projection);
                if backend == ApiBackend::Responses && flag {
                    assert!(matches!(&result, Err(crate::sampling::error::SamplingError::InvalidConfiguration(message)) if *message == "fork bridge identity is unavailable or mismatched"), "A2 eligible fork explicitly refuses {state} companion: {result:?}");
                    assert!(wire.exchanges.borrow().is_empty(), "A2 refused fork has no wire submission");
                } else {
                    assert!(result.is_ok(), "A2 unadmitted and interim forks keep legacy refusal behavior: {state}");
                    if backend == ApiBackend::ChatCompletions {
                        assert_eq!(native_lowered_body(&request, &backend), native_lowered_body(&original, &backend));
                    } else {
                        let before = a2_received_body(child, &original, &binding, &wire, "xai").await;
                        let after = a2_received_body(child, &request, &binding, &wire, "xai").await;
                        assert_eq!(after.raw_body, before.raw_body, "A2 {state} companion preserves noneligible fork bytes");
                        assert_eq!(after.parsed_body, before.parsed_body);
                    }
                }
                assert_native_specs(&request.tools, &original.tools, "A2 refused or ineligible request remains unchanged");
                assert_native_specs(&child.forked_tool_override.as_ref().unwrap().specs, &invalid.specs, "A2 invalid carrier remains unchanged");
                a2_assert_one_bound_build(&mut fixture.events);
            }
        }
        assert_native_specs(&snapshot.specs, &parent_specs, "A2 all fork scenarios preserve their originating snapshot");
    }).await;
}

